from __future__ import annotations

from decimal import Decimal
from typing import Any


_EMPTY = ""


def _value(row: dict | None, key: str) -> Any:
    if not row:
        return _EMPTY
    value = row.get(key, _EMPTY)
    return _EMPTY if value is None else value


def _text(row: dict | None, key: str) -> str:
    value = _value(row, key)
    return "" if value is None else str(value)


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == _EMPTY else value


def _number(value: Any) -> Decimal:
    value = _nvl(value, 0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool):
        return Decimal(int(value))
    return Decimal(str(value))


def _numeric_field(row: dict | None, key: str) -> Decimal:
    return _number(_value(row, key))


def _date_eq(value: str, literal: str) -> bool:
    return value == literal


def _date_ge(value: str, other: str) -> bool:
    if value == "00000000" or other == "00000000":
        return False
    return value >= other


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _text(record, "STAT_CD")
    amount = _numeric_field(record, "AMT")
    lost_rsn = _text(record, "LOST_RSN")
    close_dt = _text(record, "CLOSE_DT")
    stage_pct = _numeric_field(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (amount >= Decimal("0")):
            errors.append(_failure("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and amount == Decimal("0"))):
            errors.append(_failure("E3002", "Won opportunity requires amount"))

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_failure("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _date_eq(close_dt, "00000000"))):
            errors.append(_failure("E3004", "Won opportunity requires close date"))

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _text(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(_failure("E3005", "Cannot reopen a won opportunity"))

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (stat_cd == "P" and stage_pct == Decimal("10"))
            or (stat_cd == "Q" and stage_pct == Decimal("25"))
            or (stat_cd == "N" and stage_pct == Decimal("60"))
            or (stat_cd == "W" and stage_pct == Decimal("100"))
            or (stat_cd == "L" and stage_pct == Decimal("0"))
        )
        if not stage_consistent:
            errors.append(
                _failure("E3006", "Stage percent inconsistent with status")
            )

    # OPP-007
    if event == "INSERT":
        if not (
            _date_eq(close_dt, "00000000")
            or _date_ge(close_dt, today)
        ):
            errors.append(
                _failure("E3007", "Close date in past", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
